const fs = require('fs');
const path = require('path');

// Requires n8n env var NODE_FUNCTION_ALLOW_BUILTIN=fs,path so the Code
// node sandbox is permitted to require these Node builtins.
const baseDir = '/data/test_corpus/sample_app_clean';

function walk(dir) {
  let files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files = files.concat(walk(fullPath));
    } else if (entry.isFile() && entry.name.endsWith('.py')) {
      files.push(fullPath);
    }
  }
  return files;
}

const files = walk(baseDir).map((filePath) => ({
  filename: filePath,
  content: fs.readFileSync(filePath, 'utf8'),
}));

// Single item so downstream LLM nodes each run once with the FULL corpus,
// not once per file.
return [{ json: { files } }];

// Order here must match the order branches are wired into the Merge node
// (Security -> input 0, Performance -> input 1, Style/Test Coverage -> input 2)
// since Merge in "append" mode preserves that order.
const AGENT_NAMES = ['security_analyst', 'performance_analyst', 'style_test_coverage_analyst'];

function extractRawText(item) {
  if (typeof item.json.merged_response === 'string') return item.json.merged_response;
  if (Array.isArray(item.json.content)) {
    return item.json.content.filter((c) => c.type === 'text').map((c) => c.text).join('');
  }
  return '';
}

function stripCodeFences(text) {
  let result = text.trim();
  result = result.replace(/^```(?:json)?[ \t]*\r?\n?/, '');
  result = result.replace(/```[ \t]*$/, '');
  return result.trim();
}

function parseAgentOutput(item) {
  const raw = stripCodeFences(extractRawText(item));
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    return [];
  }
}

function dedupeKey(finding) {
  const shortDescription = String(finding.description || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .split(' ')
    .slice(0, 6)
    .join(' ');
  return [finding.file, finding.category, shortDescription].join('|');
}

const items = $input.all();
const allFindings = [];

items.forEach((item, index) => {
  const agentFindings = parseAgentOutput(item);
  agentFindings.forEach((finding) => {
    allFindings.push({ ...finding, source_agent: AGENT_NAMES[index] || `agent_${index}` });
  });
});

const deduped = new Map();
for (const finding of allFindings) {
  const key = dedupeKey(finding);
  if (!deduped.has(key)) {
    deduped.set(key, finding);
  }
}

const findings = Array.from(deduped.values());
const payload = JSON.stringify({ findings, generated_at: new Date().toISOString() }, null, 2);

return [{
  json: { findings, count: findings.length },
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(payload, 'utf8'), 'findings.json', 'application/json'),
  },
}];
